/// <summary>
/// Contract class for the business event <c>METDutyRollMonthlyBusinessEvents</c>
/// Created for the task - CB799.
/// </summary>
[DataContract]
public class METDutyRollMonthlyBusinessEventsContract extends BusinessEventsContract
{
    str             immediateChange;
    ItemId          items;
    InventSiteId    sites;
    const str       delimeter = ', ';

}

Method.Source:
/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemList">List of items</param>
/// <returns>List of items</returns>
[DataMember('Items'), BusinessEventsDataMember("@MET:ItemQuery")]
public ItemId parmItem(ItemId _items = items)
{
    items = _items;
    return items;
}

/// <summary>
/// Site
/// </summary>
/// <param name = "_siteList">List of Sites</param>
/// <returns>List of sites</returns>
[DataMember('Sites'), BusinessEventsDataMember("@SYS103211")]
public InventSiteId parmSite(InventSiteId _sites = sites)
{
    sites = _sites;
    return sites;
}

/// <summary>
/// Immediate change parameter
/// </summary>
/// <param name = "_immediateChange">Immediate change</param>
/// <returns>str</returns>
[DataMember('immediateChange'), BusinessEventsDataMember("@MET:ImmediateChange")]
public str parmImmediateChange(str _immediateChange = immediateChange)
{
    immediateChange = _immediateChange;
    return immediateChange;
}

    /// <summary>
    /// Call the initialize method.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <param name = "_delimeter">str</param>
    /// <returns>METDutyRollMonthlyBusinessEventsContract</returns>
    public METDutyRollMonthlyBusinessEventsContract initialize(METDutyRollMonthlyContract _contract, str _delimeter = ',')
    {
        METDutyRollMonthlyBusinessEventsContract contract = new METDutyRollMonthlyBusinessEventsContract();

        sites = this.getSites(_contract, _delimeter);

        if (_contract.parmAdHoc())
        {
            items = this.getItems(_contract, _delimeter);
        }

        if (_contract.parmImmediateChange() == NoYes::Yes)
        {
            immediateChange = 'Yes';
        }
        else
        {
            immediateChange = 'No';
        }

        return contract;
    }

    /// <summary>
    /// Call the initialize method.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <returns>METDutyRollMonthlyBusinessEventsContract</returns>
    public static METDutyRollMonthlyBusinessEventsContract sendEvent(METDutyRollMonthlyContract _contract)
    {
        METDutyRollMonthlyBusinessEventsContract contract = new METDutyRollMonthlyBusinessEventsContract();
        contract.initialize(_contract, delimeter);

        return contract;
    }

    /// <summary>
    /// Get the list of items selected on the paarameter.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <param name = "_delimeter">str</param>
    /// <returns>items</returns>
    public ItemId getItems(METDutyRollMonthlyContract _contract, str _delimeter)
    {
        ListIterator itemListIterator = new ListIterator(_contract.parmItemList());
            
        while (itemListIterator.more())
        {
            items += itemListIterator.value();

            itemListIterator.next();

            if (itemListIterator.more())
            {
                items += _delimeter;
            }
        }
        return items;
    }

    /// <summary>
    /// Get the list of sites selected on the parameter.
    /// </summary>
    /// <param name = "_contract">METDutyRollMonthlyContract</param>
    /// <param name = "_delimeter">str</param>
    /// <returns>sites</returns>
    public InventSiteId getSites(METDutyRollMonthlyContract _contract, str _delimeter)
    {
        ListIterator siteListIterator = new ListIterator(_contract.parmSiteList());
            
        while (siteListIterator.more())
        {
            sites += siteListIterator.value();

            siteListIterator.next();

            if (siteListIterator.more())
            {
                sites += _delimeter;
            }
        }
        return sites;
    }
